INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (1,'Disposez dans une cocotte les morceaux d''agneau, le cube de bouillon, le romarin et le laurier, la carotte coupée en rondelle, le jus de citron et couvrez d''eau.',1,'fr',1);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (2,'Couvrez et laissez cuire environ 1 heure. Réservez la viande et la carotte. Jetez le romarin et le laurier.',1,'fr',2);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (3,'Dans une casserole, préparez le roux en faisant fondre le beurre puis en y ajoutant la farine. Bien mélangez puis ajoutez peu à peu le bouillon de cuisson de la viande.',1,'fr',3);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (4,'Mélangez le jaune d''oeuf et la crème dans un bol puis ajoutez à la sauce.',1,'fr',4);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (5,'Rajoutez la viande et la carotte, puis laissez mijotez doucement (surtout ne pas faire bouillir sinon, la sauce tournerait). Rajoutez des rondelles de cornichons, si vous aimez.
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (6,'Dégustez si possible réchauffé, avec des pommes de terre vapeur.',1,'fr',6);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (7,'Couper le poulet en morceaux et piquer ceux-ci sur des brochettes en bois. 
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (8,'Assaisonner, puis les rôtir sur tous les côtés dans l’huile chaude. ',1,'fr',2);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (9,'Parer les carottes et le poireau, puis les tailler en fines lanières. ',1,'fr',3);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (10,'Plonger les légumes dans le bouillon de poule et les faire cuire pendant 3 minutes environ, sans trop les laisser ramollir. ',1,'fr',4);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (11,'Affiner avec la crème à café. ',1,'fr',5);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (12,'Ajouter la ciboulette et napper les brochettes de sauce.',1,'fr',6);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (13,'Couper la viande en fines lamelles.',2,'fr',1);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (14,'Chauffer le beurre dans une poêle, y mettre la viande et tout en remuant la faire revenir de tous les côtés. ',2,'fr',2);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (15,'Assaisonner légèrement de poivre.',2,'fr',3);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (16,'Ajouter le cognac et faire flamber.',2,'fr',4);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (17,'Incorporer la crème fraîche en remuant et laisser cuire doucement à petit feu pendant 8 à 10min. Si nécessaire, verser encore un peu de crème.',2,'fr',5);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (18,'Battre le jaune d''œuf et le laisser couler dans la sauce en train de bouillir. Retirer la poêle du feu.',2,'fr',6);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (19,'Dresser la viande sur un plat chauffé, saupoudrer de persil et servir.',2,'fr',7);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (20,'Émincez votre dinde en petits morceaux.',3,'fr',1);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (21,'Faites chauffer l''huile d''olive dans une cocotte.',3,'fr',2);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (22,'Quand l''huile est chaude ajoutez vos morceaux de dinde, salez, poivrez puis faites les dorer à feu vif.',3,'fr',3);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (23,'Quand ils ont doré, réservez les dans une assiette.',3,'fr',4);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (24,'Faites revenir votre poivron en morceaux environ 10 minutes à feu moyen en ajoutant de l''huile d''olive si nécessaire.',3,'fr',5);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (25,'Ajoutez les échalotes, les gousses d''ail émincées et faites revenir 5 minutes en remuant souvent.',3,'fr',6);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (26,'Ajouter les champignons émincés et faites les revenir 5 minutes.',3,'fr',7);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (27,'Remettez l''émincé de dinde dans votre cocotte avec le reste de vos légumes et mélanger.',3,'fr',8);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (28,'Saupoudrez le curry, le curcuma et le gingembre.',3,'fr',9);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (29,'Ajouter de l''eau (attention à ne pas mettre trop d''eau) pour recouvrir l''ensemble et mélanger.',3,'fr',10);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (30,'Ajouter le romarin, le thym, la ciboulette et le basilic émincés.',3,'fr',11);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (31,'Salez, poivrez et laisser mijoter à feu doux pendant 30 minutes, le temps que la sauce réduise un peu.',3,'fr',12);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (32,'Ajouter le lait de coco, une cuillère de Maïzena, remuez et laisser mijoter à feu très doux 1 heure.',3,'fr',13);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (33,'Votre sauce est prête quand elle à assez réduite et que sa consistance est onctueuse.',3,'fr',14);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (34,'Faites cuire votre riz et servez le accompagné de votre sauce au curry.',3,'fr',15);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (35,'Eplucher et émincer les oignons. Les faire revenir dans le beurre et l''huile. ',4,'fr',1);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (36,'Quand les oignons ont bien fondus et forment un "amas pâteux", ajouter la viande coupée en morceaux de taille moyenne. ',4,'fr',2);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (37,'Ajouter le concentré de tomates, sel poivre, bouquet garni et bouillon de boeuf. Fermer la cocotte car la viande ne doit pas dorer.',4,'fr',3);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (38,'Laisser cuire à feu très doux pendant 3 heures.',4,'fr',4);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (39,'Ajouter le paprika une heure avant de servir.',4,'fr',5);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (40,'Incorporer la crème fraîche au dernier moment, laisser chauffer et servir.',4,'fr',6);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (41,'Emincer la laitue en lamelles et éplucher et couper les carottes en rondelles.',5,'fr',1);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (42,'Faire revenir l''oignon émincé dans du beurre, y ajouter la laitue ainsi que les carottes.',5,'fr',2);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (43,'Saler, poivrer.',5,'fr',3);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (44,'Recouvrir avec du bouillon et laisser cuire une dizaine de minutes.',5,'fr',4);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (45,'Ajouter les petits pois et cuire encore 10 minutes.',5,'fr',5);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (46,'Egoutter s''il reste du liquide et saupoudrer de persil.',5,'fr',6);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (47,'Faire cuire les pâtes.',6,'fr',1);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (48,'Faire revenir l''ail et les oignons dans une sauteuse dans de l''huile d''olive.',6,'fr',2);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (49,'Ajouter les chanterelles, les laisser dégorger en remuant régulièrement.',6,'fr',3);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (50,'Laisser l''eau s''évaporer.',6,'fr',4);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (51,'Ajouter le verre de vin blanc et la crème.',6,'fr',5);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (52,'Laisser épaissir à feu moyen.',6,'fr',6);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (53,'Rectifier l''assaisonnement, ajouter le persil.',6,'fr',7);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (54,'Servir avec les pâtes bien chaudes.',6,'fr',8);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (55,'Peler et couper en deux dans le sens de la longueur les pommes de terre.',7,'fr',1);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (56,'Les cuire dans de l’eau sans trop les laisser ramollir',7,'fr',2);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (57,'Bien égoutter les tomates et les tailler en fines lanières.',7,'fr',3);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (58,'Faire chauffer l’huile d’olive et y faire dorer lentement les pommes de terre. ',7,'fr',4);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (59,'Ajouter les tomates, l’ail et le romarin, puis faire rissoler le tout encore 2 minutes.',7,'fr',5);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (60,'Assaisonner.',7,'fr',6);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (61,'Couper la viande en fines lamelles.',8,'fr',1);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (62,'Verser l''huile dans une cocotte minute puis ajouter le boeuf, les oignons hachés, le concentré de tomate, la sauce tomate, l''ail haché, le sel, le poivre, et le reste des épices.',8,'fr',2);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (63,'Faites revenir 2 à 3 min à feu fort tout en remuant, puis ajouter l''eau, de façon à ce que la viande soit recouverte par 2 fois son volume environ.',8,'fr',3);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (64,'Fermer la cocotte minute puis faire cuire 30 min à partir de la rotation de la soupape.',8,'fr',4);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (65,'Eplucher les pommes de terres et les carottes.',8,'fr',5);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (66,'Laver et ciseler le persil.',8,'fr',6);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (67,'Couper les pommes de terres en quatre et les carottes en rondelles.',8,'fr',7);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (68,'Au bout des 35 minutes arrêter la cuisson, ouvrir votre cocotte, rectifier l''assaisonnement si nécessaire, ajouter le persil, les carottes, les pommes de terres et vos petits pois. (Vérifier le niveau d''eau, les légumes doivent être recouverts).',8,'fr',8);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (69,'Relancer la cuisson pendant encore 25 minutes à partir de la rotation de la soupape.',8,'fr',9);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (70,'Emincer finement les oignons, les champignons et couper le poulet en dés d''environ 2 cm.',9,'fr',1);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (71,'Préparer le bouillon de poule.',9,'fr',2);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (72,'Effeuiller et ciseler finement la coriandre.',9,'fr',3);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (73,'Dans un fait-tout ou une grande sauteuse, faire chauffer 4 ou 5 cuillerées à soupe d''huile d''olive.',9,'fr',4);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (74,'Faire revenir les oignons dans l''huile 5 min environ le temps qu''ils dorent et fondent.',9,'fr',5);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (75,'Baisser le feu.',9,'fr',6);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (76,'Ajouter le riz et les champignons et faire chauffer 3 min environ en remuant sans cesse. Saler un peu.',9,'fr',7);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (77,'Ajouter le vin blanc et laisser évaporer.',9,'fr',8);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (78,'Lorsqu''il s''est évaporé, ajouter 2 louches de bouillon. Attendre l''évaporation.',9,'fr',9);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (79,'Ajouter une cuillère à café de mélange 4 épices.',9,'fr',10);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (80,'Continuer ainsi de suite jusqu''à finir la casserole de bouillon, et qu''il soit complètement évaporé du riz.',9,'fr',11);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (81,'Pendant la cuisson du riz, préparer le poulet : dans un wok ou une sauteuse (la viande sera plus tendre dans le wok), faire chauffer un peu d''huile d''olive.',9,'fr',12);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (82,'Ajouter les morceaux de poulet, et immédiatement baisser le feu. Si le poulet cuit lentement sur feu doux il sera plus tendre. Saler un peu.',9,'fr',13);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (83,'Remuer sans cesse, sans oublier de surveiller la cuisson et l''arrosage du riz !',9,'fr',14);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (84,'Lorsque le poulet est devenu opaque, ajouter la sauce soja et le miel. Bien mélanger.',9,'fr',15);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (85,'Laisser le poulet cuire encore 2 minutes.',9,'fr',16);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (86,'Lorsque la cuisson du riz est terminée (réserve de bouillon épuisée et bouillon), ajouter le poulet et son jus de cuisson au risotto.',9,'fr',17);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (87,'Bien mélanger, puis ajouter la crème fraîche et mélanger de nouveau.',9,'fr',18);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (88,'Ajustez l''assaisonnement sel/poivre et servir bien chaud, le tout parsemé de coriandre.',9,'fr',19);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (89,'Faire cuire le riz dans une casserole d''eau bouillante salée.',10,'fr',1);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (90,'L''égoutter et le réserver.',10,'fr',2);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (91,'Hacher l''ail, l''oignon, et les poivrons.',10,'fr',3);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (92,'Faire chauffer l''huile d''olive dans une grande poêle, y jeter les poivron, l''ail et l''oignon.',10,'fr',4);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (93,'Faire dorer.',10,'fr',5);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (94,'Y ajouter les crevettes et les faire dorer.',10,'fr',6);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (95,'Ajouter 2 cuillères à soupe de curry en poudre.',10,'fr',8);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (96,'Ajouter le poulet coupé en petits morceaux, laisser dorer.',10,'fr',9);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (97,'Incorporer ensuite, les dés de tomate et les cubes de courgettes, laisser cuire à feu doux.',10,'fr',10);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (98,'Ajouter à nouveau du curry en poudre et de la sauce soja.',10,'fr',11);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (99,'Couvrir avec le riz, et remuer de temps en temps avec une spatule.',10,'fr',12);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (100,'Cuire les pâtes dans de l''eau bouillante, additionnée de bouillon d''épices pour pâtes.',11,'fr',1);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (101,'Parer les champignons, émincer les plus gros et étuver avec l''échalote dans l''huile grésillante. ',11,'fr',2);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (102,'Déglacer au vin blanc.',11,'fr',3);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (103,'Réduire légèrement. Affiner avec la crème. ',11,'fr',4);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (104,'Réchauffer et en napper les pâtes soigneusement égouttées. ',11,'fr',5);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (105,'Servir chaud',6,'fr',81);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (106,'Place in a casserole the pieces of lamb, the cube of broth, rosemary and bay leaf, the sliced carrot, the lemon juice and cover with water.',12,'en',1);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (107,'Cover and cook for about 1 hour. Set aside the meat and carrot. Discard the rosemary and bay leaves.',12,'en',2);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (108,'In a saucepan, prepare the roux by melting the butter and adding the flour. Mix well and then add gradually the broth of the meat.',12,'en',3);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (109,'Mix the egg yolk and cream in a bowl and add to the sauce.',12,'en',4);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (110,'Add the meat and carrot, then simmer gently (especially not boil otherwise, the sauce would turn). Add more pickle slices, if you like.',12,'en',5);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (111,'If possible, enjoy warm, with steamed potatoes.',12,'en',6);
