INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (115,'Dip the vegetables in the chicken broth and cook for about 3 minutes, without letting them soften too much.',12,'en',4);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (116,'Refine with coffee cream. ',12,'en',5);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (117,'Add chives and drizzle with sauce.',12,'en',6);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (118,'Cut the meat into thin strips..',13,'en',1);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (119,'Heat the butter in a frying pan, add the meat and stir it to brown from all sides. ',13,'en',2);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (120,'Season lightly with pepper.',13,'en',3);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (121,'Add the cognac and set on fire.',13,'en',4);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (122,'Stir in the crème fraîche and cook gently over low heat for 8 to 10 minutes. If necessary, add a little more cream.',13,'en',5);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (123,'Beat the egg yolk and let it pour into the boiling sauce. Remove the pan from the heat.',13,'en',6);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (124,'Place the meat on a heated dish, sprinkle with parsley and serve.',13,'en',7);
