INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (136,'Season with salt, pepper and simmer on low heat for 30 minutes until the sauce reduces slightly.',14,'en',12);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (137,'Add the coconut milk, a spoonful of cornstarch, stir and simmer over very low heat for 1 hour.',14,'en',13);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (138,'Your sauce is ready when it is reduced enough and its consistency is creamy.',14,'en',14);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (139,'Cook your rice and serve it with your curry sauce.',14,'en',15);
