INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (141,'When the onions have melted well and form a "pasty cluster", add the meat cut into medium sized pieces. ',15,'en',2);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (142,'Add the tomato paste, salt and pepper, bouquet garni and beef broth. Close the casserole because the meat should not brown.',15,'en',3);
