INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (144,'Add the paprika an hour before serving.',15,'en',5);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (145,'Stir in the crème fraîche at the last moment, let it heat and serve.',15,'en',6);
