INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (148,'salt, add pepper.',16,'en',3);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (149,'Cover with broth and cook for about 10 minutes.',16,'en',4);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (150,'Add the peas and cook for another 10 minutes.',16,'en',5);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (151,'Drain if liquid remains and sprinkle with parsley.',16,'en',6);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (152,'Cook the pasta.',17,'en',1);
