INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (159,'Serve with hot pasta.',17,'en',8);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (160,'Peel and cut the potatoes in half lengthwise.',18,'en',1);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (161,'Cook them in water without letting them soften.',18,'en',2);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (162,'Drain the tomatoes well and cut into thin strips.',18,'en',3);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (163,'Heat the olive oil and slowly brown the potatoes. ',18,'en',4);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (164,'Add the tomatoes, garlic and rosemary, then cook for another 2 minutes.',18,'en',5);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (165,'Season.',18,'en',6);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (166,'Cut the beef into small cubes of about 3 cm and chop the onions.',19,'en',1);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (167,'Pour the oil into a pressure cooker and add the beef, chopped onions, tomato paste, tomato sauce, chopped garlic, salt, pepper, and the rest of the spices.',19,'en',2);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (168,'Sauté 2-3 min over high heat while stirring, then add water so that the meat is covered by about 2 times its volume.',19,'en',3);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (169,'Close the pressure cooker and cook for 30 minutes from the turn of the valve.',19,'en',4);
