INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (171,'Wash and chop the parsley.',19,'en',6);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (172,'Cut the potatoes in quarters and the carrots into rings.',19,'en',7);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (173,'After 35 minutes stop cooking, open your casserole, adjust the seasoning if necessary, add parsley, carrots, potatoes and peas. (Check water level, vegetables should be covered).',19,'en',8);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (174,'Restart cooking for another 25 minutes from valve rotation.',19,'en',9);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (175,'Finely chop the onions, mushrooms and cut the chicken into about 2 cm cubes.',20,'en',1);
