INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (180,'Reduce the heat.',20,'en',6);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (181,'Add the rice and mushrooms and heat for about 3 minutes, stirring constantly. Season with a little salt.',20,'en',7);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (182,'Add the white wine and let it evaporate.',20,'en',8);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (183,'When it has evaporated, add 2 ladles of broth. Wait for evaporation.',20,'en',9);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (184,'Add a teaspoon of 4-spice mixture.',20,'en',10);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (185,'Continue until the broth is finished, and the rice has completely evaporated.',20,'en',11);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (186,'While cooking the rice, prepare the chicken: in a wok or sauté pan (the meat will be softer in the wok), heat some olive oil.',20,'en',12);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (187,'Add the chicken pieces, and immediately lower the heat. If the chicken is cooked slowly over low heat it will be softer. Season with a little salt.',20,'en',13);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (188,'Stir constantly, without forgetting to watch the cooking and watering of the rice!',20,'en',14);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (189,'When the chicken is opaque, add soy sauce and honey. Mix well.',20,'en',15);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (190,'Let the chicken cook for another 2 minutes.',20,'en',16);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (191,'When the rice is cooked (stock of broth exhausted and broth), add chicken and its cooking juice to the risotto.',20,'en',17);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (192,'Mix well, then add the fresh cream and stir again.',20,'en',18);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (193,'Adjust the seasoning salt/pepper and serve hot, all sprinkled with coriander.',20,'en',19);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (194,'Cook the rice in a saucepan of salted boiling water.',21,'en',1);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (195,'Drain and set aside.',21,'en',2);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (196,'Chop the garlic, onion and peppers.',21,'en',3);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (197,'Heat the olive oil in a large skillet, add the pepper, garlic and onion.',21,'en',4);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (198,'Brown it.',21,'en',5);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (199,'Add the shrimp and brown.',21,'en',6);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (200,'Add 2 tablespoons of curry powder.',21,'en',8);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (201,'Add the chicken cut into small pieces, let it brown.',21,'en',9);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (202,'Then add the diced tomatoes and the zucchini cubes, cook over low heat.',21,'en',10);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (203,'Add curry powder and soy sauce again.',21,'en',11);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (204,'Cover with the rice, and stir from time to time with a spatula.',21,'en',12);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (205,'Cook the pasta in boiling water, with added spice broth for pasta.',22,'en',1);
