INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (210,'Serve warm.',17,'en',81);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (211,'Coloque en una olla los trozos de cordero, el cubo de caldo, el romero y el laurel, la zanahoria en rodajas, el jugo de limón y cubra con agua.',23,'es',1);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (212,'Cubra y deje cocer durante aproximadamente 1 hora. Reserve la carne y la zanahoria. Deseche el romero y el laurel.',23,'es',2);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (213,'En una cacerola, prepare el roux derritiendo la mantequilla y añadiendo la harina. Mezcle bien y agregue poco a poco el caldo de cocción de la carne.',23,'es',3);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (214,'Mezcle la yema de huevo y la crema en un bol y añádalo a la salsa.',23,'es',4);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (215,'Añada la carne y la zanahoria, luego deje cocer a fuego muy lento (sin hervir, para que la salsa no se corte). Añada rodajas de pepinillos si lo desea.',23,'es',5);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (216,'Disfrútelo, si es posible, recalentado y acompañado de patatas al vapor.',23,'es',6);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (217,'Corte el pollo en trozos y ensártelos en brochetas de madera.',1,'es',1);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (218,'Sazone y dórelos por todos los lados en aceite caliente.',1,'es',2);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (219,'Limpie las zanahorias y el puerro, luego córtelos en tiras finas.',1,'es',3);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (220,'Sumerja las verduras en el caldo de pollo y cuézalas durante unos 3 minutos, sin dejarlas ablandar demasiado.',1,'es',4);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (221,'Perfilar con la crema de café.',1,'es',5);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (222,'Añada el cebollino y cubra las brochetas con la salsa.',1,'es',6);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (223,'Corte la carne en tiras finas.',2,'es',1);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (224,'Caliente la mantequilla en una sartén, añada la carne y rehógela removiendo hasta dorarla por todos los lados.',2,'es',2);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (225,'Sazone ligeramente con pimienta.',2,'es',3);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (226,'Añada el coñac y flambéelo.',2,'es',4);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (227,'Incorpore la crema fresca removiendo y deje cocer a fuego muy lento durante 8 a 10 minutos. Si es necesario, añada un poco más de crema.',2,'es',5);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (228,'Bata la yema de huevo y déjela caer en la salsa hirviendo. Retire la sartén del fuego.',2,'es',6);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (229,'Coloque la carne en una fuente caliente, espolvoree con perejil y sirva.',2,'es',7);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (230,'Corte su pavo en trozos pequeños.',3,'es',1);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (231,'Caliente el aceite de oliva en una olla.',3,'es',2);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (232,'Cuando el aceite esté caliente, añada los trozos de pavo, salpimiente y dórelos a fuego fuerte.',3,'es',3);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (233,'Cuando estén dorados, resérvelos en un plato.',3,'es',4);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (234,'Saltee el pimiento en trozos durante unos 10 minutos a fuego medio, añadiendo aceite de oliva si es necesario.',3,'es',5);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (235,'Añada las chalotas y los dientes de ajo picados, y rehogue durante 5 minutos removiendo con frecuencia.',3,'es',6);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (236,'Añada los champiñones laminados y rehógalos durante 5 minutos.',3,'es',7);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (237,'Vuelva a poner el pavo en tiras en la olla junto con el resto de las verduras y mezcle.',3,'es',8);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (238,'Espolvoree el curry, la cúrcuma y el jengibre.',3,'es',9);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (239,'Añada agua (sin excederse) para cubrir el conjunto y mezcle.',3,'es',10);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (240,'Añada el romero, el tomillo, el cebollino y la albahaca picados.',3,'es',11);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (241,'Sale, pimiente y deje cocer a fuego lento durante 30 minutos, hasta que la salsa reduzca un poco.',3,'es',12);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (242,'Añada la leche de coco, una cucharada de maicena, mezcle y deje cocer a fuego muy lento durante 1 hora.',3,'es',13);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (243,'La salsa está lista cuando haya reducido lo suficiente y tenga una consistencia cremosa.',3,'es',14);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (244,'Cocine el arroz y sírvalo acompañado de su salsa de curry.',3,'es',15);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (245,'Pele y pique finamente las cebollas. Saltéelas en mantequilla y aceite.',4,'es',1);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (246,'Cuando las cebollas estén bien pochadas y formen una pasta, añada la carne cortada en trozos medianos.',4,'es',2);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (247,'Añada el concentrado de tomate, sal, pimienta, el bouquet garni y el caldo de ternera. Cierre la olla para evitar que la carne dore.',4,'es',3);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (248,'Deje cocer a fuego muy lento durante 3 horas.',4,'es',4);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (249,'Añada el pimentón una hora antes de servir.',4,'es',5);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (250,'Incorpore la crema fresca en el último momento, deje calentar y sirva.',4,'es',6);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (251,'Corte la lechuga en tiras y pele y corte las zanahorias en rodajas.',5,'es',1);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (252,'Rehogue la cebolla picada en mantequilla y añada la lechuga y las zanahorias.',5,'es',2);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (253,'Sazone con sal y pimienta.',5,'es',3);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (254,'Cubra con caldo y deje cocer unos diez minutos.',5,'es',4);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (255,'Añada los guisantes y cocine 10 minutos más.',5,'es',5);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (256,'Escurra si queda líquido y espolvoree con perejil.',5,'es',6);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (257,'Cueza la pasta.',6,'es',1);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (258,'Rehogue el ajo y la cebolla en una sartén con aceite de oliva.',6,'es',2);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (259,'Añada las setas y déjelas soltar su agua, removiendo regularmente.',6,'es',3);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (260,'Deje que el agua se evapore.',6,'es',4);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (261,'Añada el vaso de vino blanco y la crema.',6,'es',5);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (262,'Deje espesar a fuego medio.',6,'es',6);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (263,'Ajuste el sazonamiento y añada el perejil.',6,'es',7);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (264,'Sirva con la pasta bien caliente.',6,'es',8);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (265,'Pele las patatas y córtelas por la mitad a lo largo.',7,'es',1);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (266,'Cuézalas en agua sin dejarlas ablandar demasiado.',7,'es',2);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (267,'Escurra bien los tomates y córtelos en tiras finas.',7,'es',3);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (268,'Caliente el aceite de oliva y dore lentamente las patatas.',7,'es',4);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (269,'Añada los tomates, el ajo y el romero, y rehogue todo durante 2 minutos más.',7,'es',5);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (270,'Sazone.',7,'es',6);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (271,'Corte la carne de res en cubos de unos 3 cm y pique las cebollas.',8,'es',1);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (272,'Vierta el aceite en una olla a presión y añada la carne, las cebollas picadas, el concentrado de tomate, la salsa de tomate, el ajo picado, la sal, la pimienta y el resto de las especias.',8,'es',2);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (273,'Rehogue durante 2 a 3 minutos a fuego fuerte, removiendo, luego añada agua hasta cubrir la carne con aproximadamente el doble de su volumen.',8,'es',3);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (274,'Cierre la olla a presión y cocine durante 30 minutos a partir de la rotación de la válvula.',8,'es',4);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (275,'Pele las patatas y las zanahorias.',8,'es',5);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (276,'Lave y pique finamente el perejil.',8,'es',6);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (277,'Corte las patatas en cuartos y las zanahorias en rodajas.',8,'es',7);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (278,'Tras 35 minutos, detenga la cocción, abra la olla, ajuste el sazonamiento si es necesario y añada el perejil, las zanahorias, las patatas y los guisantes. (Compruebe el nivel de agua: las verduras deben quedar cubiertas).',8,'es',8);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (279,'Reinicie la cocción durante otros 25 minutos a partir de la rotación de la válvula.',8,'es',9);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (280,'Pique finamente las cebollas y los champiñones, y corte el pollo en dados de unos 2 cm.',9,'es',1);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (281,'Prepare el caldo de pollo.',9,'es',2);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (282,'Deshoje y pique finamente el cilantro.',9,'es',3);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (283,'En una olla grande o sartén profunda, caliente 4 o 5 cucharadas de aceite de oliva.',9,'es',4);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (284,'Rehogue las cebollas en el aceite durante unos 5 minutos, hasta que doren y se ablanden.',9,'es',5);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (285,'Baje el fuego.',9,'es',6);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (286,'Añada el arroz y los champiñones y caliente unos 3 minutos, removiendo sin parar. Añada un poco de sal.',9,'es',7);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (287,'Añada el vino blanco y deje que se evapore.',9,'es',8);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (288,'Cuando se haya evaporado, añada dos cucharones de caldo y espere a que se absorba.',9,'es',9);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (289,'Añada una cucharadita de mezcla de cuatro especias.',9,'es',10);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (290,'Continúe de la misma manera hasta terminar el caldo y que el arroz lo haya absorbido por completo.',9,'es',11);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (291,'Mientras se cocina el arroz, prepare el pollo: en un wok o sartén honda (la carne queda más tierna en el wok), caliente un poco de aceite de oliva.',9,'es',12);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (292,'Añada los trozos de pollo y baje el fuego de inmediato. Si el pollo se cocina lentamente a fuego suave, quedará más tierno. Añada un poco de sal.',9,'es',13);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (293,'Remueva constantemente, sin olvidar vigilar la cocción y el riego del arroz.',9,'es',14);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (294,'Cuando el pollo esté opaco, añada la salsa de soja y la miel. Mezcle bien.',9,'es',15);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (295,'Deje que el pollo se cocine 2 minutos más.',9,'es',16);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (296,'Cuando el arroz esté listo (el caldo se haya agotado y absorbido), añada el pollo y su jugo de cocción al risotto.',9,'es',17);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (297,'Mezcle bien, luego añada la crema fresca y mezcle de nuevo.',9,'es',18);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (298,'Ajuste la sal y la pimienta y sirva bien caliente, espolvoreado con cilantro.',9,'es',19);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (299,'Cueza el arroz en una olla con agua hirviendo salada.',10,'es',1);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (300,'Escúrralo y resérvelo.',10,'es',2);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (301,'Pique el ajo, la cebolla y los pimientos.',10,'es',3);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (302,'Caliente el aceite de oliva en una sartén grande y añada los pimientos, el ajo y la cebolla.',10,'es',4);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (303,'Déjelos dorar.',10,'es',5);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (304,'Añada las gambas y dórelas.',10,'es',6);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (305,'Añada dos cucharadas de curry en polvo.',10,'es',8);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (306,'Añada el pollo cortado en trozos pequeños y déjelo dorar.',10,'es',9);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (307,'Incorpore los dados de tomate y los cubos de calabacín, y deje cocinar a fuego lento.',10,'es',10);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (308,'Añada nuevamente curry en polvo y salsa de soja.',10,'es',11);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (309,'Cubra con el arroz y remueva de vez en cuando con una espátula.',10,'es',12);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (310,'Cueza la pasta en agua hirviendo con caldo de especias para pasta.',11,'es',1);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (311,'Limpie los champiñones, corte en láminas los más grandes y rehógalos con la chalota en el aceite caliente.',11,'es',2);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (312,'Desglase con vino blanco.',11,'es',3);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (313,'Deje reducir ligeramente y añada la crema para afinar la salsa.',11,'es',4);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (314,'Caliente la salsa y viértala sobre la pasta bien escurrida.',11,'es',5);
INSERT INTO "Instructions" ("id","instruction","recipe_id","language","rank") VALUES (315,'Sirva caliente.',6,'es',81);
